{
  "interpretation": {
    "name": "TightenForkliftF35OnLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Obtain the F35 tightening program, bring nutrunner NR7 to station st3, tighten, evaluate and record the result, then return the tool to the crib.",
    "constraints": [
      "get-program is executed first, before any other Step",
      "NR7 is reserved before use and released after it is returned",
      "transport-tool to station completes before configure-tool and tighten-fasteners",
      "transport-tool is delegated to agvexecutor",
      "the tightening is evaluated and recorded (quality policy)",
      "NR7 is returned to the crib after tightening",
      "no numeric process values appear in the Recipe"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-nr7-tighten-f35",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": ["reserve-tool-step"],
            "dep": [],
